from collections import Counter
def solve(g):
    H,W=len(g),len(g[0])
    best=None
    for h in range(1,H+1):
        for w in range(1,W+1):
            cnt={}
            ok=True
            for i in range(H):
                for j in range(W):
                    if g[i][j]!=2:
                        k=(i%h,j%w)
                        if k in cnt and cnt[k]!=g[i][j]: ok=False;break
                        cnt[k]=g[i][j]
                if not ok:break
            if ok and len(cnt)==h*w:
                best=(h,w); break
        if best: break
    h,w=best
    T={}
    for i in range(H):
        for j in range(W):
            if g[i][j]!=2: T[(i%h,j%w)]=g[i][j]
    # fallback for classes lacking data: inherit from nearest vertically/horizontally
    fill=lambda r,c:T.get((r,c)) or T.get((r,0)) or T.get(0,c) or list(T.values())[0]
    return [[fill(i%h,j%w) if g[i][j]==2 else g[i][j] for j in range(W)] for i in range(H)]
